{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration, so incomplete multipart uploads can persist indefinitely and consume storage."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "No S3 Public Access Block is associated with this bucket, allowing future bucket policies or ACL changes to expose dashboard content publicly."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 bucket does not block public ACLs",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "CRITICAL",
      "explanation": "The bucket does not explicitly block public ACLs, so a later ACL change could make objects or the bucket publicly accessible."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 bucket access logging is disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The bucket has no server access logging configuration, reducing visibility into requests made against the administrative dashboard content."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket lacks cross-region replication",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket has no cross-region replication configuration, leaving its contents without geographic redundancy if the source region becomes unavailable."
    }
  ],
  "patched_code": "variable "admin_dashboard_access_log_bucket" {
  description = "Name of an existing same-region S3 bucket configured to receive server access logs."
  type        = string
}

variable "admin_dashboard_replication_role_arn" {
  description = "ARN of the IAM role authorized to replicate objects from the admin dashboard bucket."
  type        = string
}

variable "admin_dashboard_replication_destination_bucket_arn" {
  description = "ARN of an existing versioned S3 destination bucket in another AWS region."
  type        = string
}

resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_logging" "admin_dashboard" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = var.admin_dashboard_access_log_bucket
  target_prefix = "admin-dashboard/"
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "admin_dashboard" {
  depends_on = [aws_s3_bucket_versioning.admin_dashboard]

  bucket = aws_s3_bucket.admin_dashboard.id
  role   = var.admin_dashboard_replication_role_arn

  rule {
    id       = "cross-region-replication"
    priority = 1
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    destination {
      bucket = var.admin_dashboard_replication_destination_bucket_arn
    }
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block, lifecycle cleanup, server access logging, versioning, and cross-region replication. The logging destination, replication destination, and authorized replication role are required as inputs so no credentials or environment-specific identifiers are embedded."
}
